import json
import numpy as np
from html import escape


def write_report(path, metrics, gbm, ou, observations):
    def envelope(values):return [np.quantile(values,q,axis=1).tolist() for q in [.1,.5,.9]]
    data=json.dumps({'gbm':envelope(gbm),'ou':envelope(ou),'posterior':observations.p_state1.tolist(),
                     'cut':metrics['hmm_train_rows']},allow_nan=False).replace('<','\\u003c')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>stochastic512 · Process atelier</title><style>*{box-sizing:border-box}body{margin:0;background:#f0eee8;color:#20312e;font:16px system-ui}main{max-width:1200px;margin:auto;padding:40px 30px}.mast{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #c9cec5;padding-bottom:22px}.wordmark{font-weight:600;letter-spacing:.12em}.badge{font-size:12px;border:1px solid #a8b5a8;padding:8px 12px;border-radius:30px;color:#476456}h1{font-family:Georgia,serif;font-size:clamp(42px,7vw,86px);font-weight:400;letter-spacing:-.055em;max-width:850px;margin-bottom:18px}p{max-width:760px;color:#61756c;line-height:1.7}.grid{display:grid;grid-template-columns:2fr 1fr;gap:22px;margin-top:36px}.panel{background:#fafbf6;border:1px solid #d1d7cc;border-radius:20px;padding:25px}.panel header{display:flex;justify-content:space-between;gap:20px;align-items:center}h2{font-size:18px;font-weight:500}button{border:1px solid #bdcabe;background:transparent;color:#527365;border-radius:25px;padding:9px 14px;cursor:pointer}button.active{background:#254d40;color:#e5f3e9}svg{width:100%;height:310px;display:block}.metric{border-bottom:1px solid #d3d9cf;padding:22px 0}.metric span{color:#658072;font-size:12px;letter-spacing:.07em;text-transform:uppercase}.metric strong{display:block;font:30px Georgia;margin-top:8px}.caption{font-size:12px;color:#6a7a6e;line-height:1.6}.posterior{margin-top:22px}.posterior svg{height:170px}.foot{margin-top:30px;padding-top:24px;border-top:1px solid #c9cec5;color:#61756c;font-size:13px;line-height:1.8}.hover{color:#336550;font:12px monospace;min-height:22px}@media(max-width:760px){main{padding:24px 16px}.grid{grid-template-columns:1fr}.panel{padding:18px}h1{font-size:50px}}</style><main><div class="mast"><div class="wordmark">STOCHASTIC512</div><div class="badge">SOURCE</div></div><h1>Patterns emerge<br>from uncertainty.</h1><p>A seeded laboratory for stochastic paths and hidden regimes. Inspect the process envelope, then follow a fitted model through observations it never trained on.</p><div class="grid"><section class="panel"><header><h2>Process ensemble</h2><div><button id="gbm" class="active" aria-pressed="true">GBM</button> <button id="ou" aria-pressed="false">OU</button></div></header><svg id="process" viewBox="0 0 760 310" role="img" aria-label="Simulated process quantile envelope"></svg><div class="hover" id="readout">Move over the ensemble to inspect quantiles.</div><p class="caption">Shaded10th–90th percentiles across PATHS synthetic paths. Center line: median. These are simulated distributions, not forecast confidence intervals.</p></section><aside class="panel"><h2>Analysis receipt</h2>METRICS<p class="caption">Fitted parameters are saved as explicit JSON and independently reloaded. Forward filtering must match before this report is produced.</p></aside></div><section class="panel posterior"><header><h2>Forward-filtered regime probability</h2><span class="badge">State1 · arbitrary component ID</span></header><svg id="regime" viewBox="0 0 1100 170" role="img" aria-label="HMM state1 probability with training holdout boundary"></svg><p class="caption">The dashed boundary separates training and holdout. Parameters stay frozen; each posterior uses only observations received so far. No future smoothing.</p></section><div class="foot">GBM uses exact discrete transitions; OU uses Euler–Maruyama at dt1/252 with fixed educational parameters. The HMM models a separate ordered scalar observation series. SOURCE_DETAIL No financial calibration, causal forecast quality or trading performance is claimed.</div></main><script>const data=PAYLOAD,ns='http://www.w3.org/2000/svg';let current='gbm';function add(svg,tag,attrs,text){const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text)e.textContent=text;svg.append(e)}function chart(){const svg=document.querySelector('#process');svg.replaceChildren();const a=data[current],n=a[0].length,lo=Math.min(...a[0]),hi=Math.max(...a[2]),pad=(hi-lo)*.08,x=i=>50+i/(n-1)*690,y=v=>265-(v-lo+pad)/(hi-lo+2*pad)*240;for(let k=0;k<4;k++){let v=lo+(hi-lo)*k/3;add(svg,'line',{x1:50,x2:740,y1:y(v),y2:y(v),stroke:'#d9dfd5'});add(svg,'text',{x:2,y:y(v)+4,fill:'#6a7a6e','font-size':11},v.toFixed(current==='ou'?2:0))}let band=a[0].map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ')+a[2].map((v,i)=>'L'+x(n-1-i)+','+y(a[2][n-1-i])).join(' ')+'Z';add(svg,'path',{d:band,fill:'#d5e8dc'});add(svg,'path',{d:a[1].map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' '),fill:'none',stroke:'#315e49','stroke-width':2});add(svg,'text',{x:50,y:297,fill:'#6a7a6e','font-size':11},'Step0');add(svg,'text',{x:670,y:297,fill:'#6a7a6e','font-size':11},'Step'+(n-1));}chart();['gbm','ou'].forEach(id=>document.getElementById(id).onclick=()=>{current=id;['gbm','ou'].forEach(k=>{document.getElementById(k).classList.toggle('active',k===id);document.getElementById(k).setAttribute('aria-pressed',k===id)});chart()});document.getElementById('process').onpointermove=e=>{let box=e.currentTarget.getBoundingClientRect(),a=data[current],i=Math.max(0,Math.min(a[0].length-1,Math.round(((e.clientX-box.left)/box.width*760-50)/690*(a[0].length-1))));document.getElementById('readout').textContent='Step'+i+' · q10 '+a[0][i].toFixed(3)+' · median '+a[1][i].toFixed(3)+' · q90 '+a[2][i].toFixed(3)};const svg=document.getElementById('regime'),x=i=>45+i/(data.posterior.length-1)*1030,y=v=>130-v*110;[0,.5,1].forEach(v=>{add(svg,'line',{x1:45,x2:1075,y1:y(v),y2:y(v),stroke:'#d9dfd5'});add(svg,'text',{x:5,y:y(v)+4,fill:'#6a7a6e','font-size':11},v.toFixed(1))});add(svg,'path',{d:data.posterior.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' '),fill:'none',stroke:'#557f69','stroke-width':1.7});add(svg,'line',{x1:x(data.cut),x2:x(data.cut),y1:10,y2:135,stroke:'#a0784d','stroke-dasharray':'4 4'});add(svg,'text',{x:x(data.cut)+8,y:154,fill:'#896c47','font-size':12},'Holdout starts');</script></html>'''
    cards=[('Training observations',metrics['hmm_train_rows']),('Holdout observations',metrics['hmm_holdout_rows']),('EM iterations',metrics['iterations'])]
    template=template.replace('METRICS',''.join(f'<div class="metric"><span>{escape(k)}</span><strong>{v}</strong></div>' for k,v in cards))
    source=metrics['source']['kind'];detail='All HMM observations and process ensembles are seeded synthetic.' if source=='seeded_synthetic' else 'The HMM uses your supplied observation file; process ensembles remain seeded synthetic.'
    path.write_text(template.replace('SOURCE_DETAIL',detail).replace('SOURCE',escape(source.upper().replace('_',' '))).replace('PATHS',str(metrics['simulation_paths'])).replace('PAYLOAD',data))
